@app.route('/api/monitor/<int:run_id>')
def monitor_run(run_id):
    """Server-Sent Events for monitoring"""
    def generate():
        start_time = time.time()
        while True:
            try:
                run = w.jobs.get_run(run_id)
                state = run.state.life_cycle_state.value
                duration = int(time.time() - start_time)
                done = state in ['TERMINATED', 'SKIPPED', 'INTERNAL_ERROR']

                result_state = run.state.result_state.value if done and run.state.result_state else state
                error = run.state.state_message if done and run.state.state_message else None

                yield f"data: {json.dumps({'state': result_state, 'duration': duration, 'done': done, 'error': error})}\n\n"

                if done:
                    break
                time.sleep(3)
            except Exception as e:
                yield f"data: {json.dumps({'state': 'ERROR', 'duration': int(time.time() - start_time), 'done': True, 'error': str(e)})}\n\n"
                break

    return Response(generate(), mimetype='text/event-stream')

