class ExecutionMonitor:
    """Tracks notebook execution and captures context"""

    def __init__(self):
        self.captured_outputs = {}
        self.datasets_used = set()
        self.cell_errors = {}

    def capture_context(self, notebook_path: str) -> Dict:
        """Capture notebook execution context"""
        try:
            # Get current notebook context
            context = {
                "notebook_path": notebook_path,
                "execution_time": datetime.now().isoformat(),
                "user": self._get_current_user(),
                "cells_executed": []
            }

            # Try to detect datasets used
            context["datasets_detected"] = self._detect_datasets()

            return context

        except Exception as e:
            return {"error": str(e)}

    def _get_current_user(self) -> str:
        """Get current user"""
        try:
            return spark.sql("SELECT current_user()").collect()[0][0]
