class CompleteBeginnerValidator:
    """Validates Complete Beginner SQL tasks"""

    def validate_task(self, code: str, task_id: str) -> Dict:
        """Route to appropriate validator"""
        if task_id == "CB_CTE":
            return self._validate_cte(code)
        elif task_id == "CB_ROW":
            return self._validate_row_number(code)
        elif task_id == "CB_SUM":
            return self._validate_sum_over(code)
        elif task_id == "CB_LAG":
            return self._validate_lag(code)
        elif task_id.startswith("CB_Q"):
            return self._validate_practice_query(code, task_id)
        else:
            return {"score": 5.0, "observations": ["✅ Task validated"], "max_score": 5.0}

    def _validate_cte(self, code: str) -> Dict:
        score = 0.0
        observations = []
        if "WITH" in code.upper():
            observations.append("✅ WITH clause used")
            score += 1.5
            cte_match = re.search(r"WITH\s+(\w+)\s+AS", code, re.IGNORECASE)
            if cte_match:
                cte_name = cte_match.group(1)
                if re.search(f"FROM\s+{cte_name}", code, re.IGNORECASE):
                    observations.append(f"✅ CTE '{cte_name}' used in main query")
                    score += 1.5
                else:
                    observations.append(f"❌ CTE '{cte_name}' not used")
                    observations.append("Check: Does your main query SELECT FROM the CTE?")
        else:
            observations.append("❌ No WITH clause found")
            observations.append("Use WITH clause to define intermediate steps")
        return {"score": min(score, 3.0), "observations": observations, "max_score": 5.0}

    def _validate_row_number(self, code: str) -> Dict:
        score = 0.0
        observations = []
        if "ROW_NUMBER()" in code.upper().replace(" ", ""):
            observations.append("✅ ROW_NUMBER() used")
            score += 1.0
            if "PARTITION BY" in code.upper():
                observations.append("✅ PARTITION BY present")
                score += 1.0
            else:
                observations.append("⚠️  Missing PARTITION BY - ranking won't restart per group")
            if "ORDER BY" in code.upper():
                observations.append("✅ ORDER BY present")
                score += 0.5
            if re.search(r"WHERE.*row.*<=|rn.*<=", code, re.IGNORECASE):
                observations.append("✅ Filters to top N")
                score += 0.5
        else:
            observations.append("❌ No ROW_NUMBER() found")
            observations.append("Use ROW_NUMBER() OVER (PARTITION BY ... ORDER BY ...)")
        return {"score": min(score, 3.0), "observations": observations, "max_score": 5.0}

    def _validate_sum_over(self, code: str) -> Dict:
        score = 0.0
        observations = []
        if re.search(r"SUM\s*\(.*?\)\s*OVER", code, re.IGNORECASE):
            observations.append("✅ SUM() OVER() used")
            score += 1.5
            if re.search(r"OVER\s*\(\s*ORDER\s+BY", code, re.IGNORECASE):
                observations.append("✅ ORDER BY in OVER (creates running total)")
                score += 1.5
            else:
                observations.append("❌ Missing ORDER BY in OVER")
                observations.append("Hint: SUM() OVER (ORDER BY date) creates running total")
        else:
            observations.append("❌ No SUM() OVER() found")
            observations.append("Use SUM(...) OVER (ORDER BY date) for running totals")
        return {"score": min(score, 3.0), "observations": observations, "max_score": 5.0}

    def _validate_lag(self, code: str) -> Dict:
        score = 0.0
        observations = []
        if re.search(r"LAG\s*\(", code, re.IGNORECASE):
            observations.append("✅ LAG() used")
            score += 1.0
            if re.search(r"LAG.*?OVER\s*\(\s*ORDER\s+BY", code, re.IGNORECASE | re.DOTALL):
                observations.append("✅ ORDER BY in LAG")
                score += 1.0
            if re.search(r"-\s*LAG|/\s*LAG|\*\s*100", code, re.IGNORECASE):
                observations.append("✅ Growth calculation detected")
                score += 1.0
            else:
                observations.append("⚠️  Are you calculating growth (current - previous)?")
        else:
            observations.append("❌ No LAG() found")
            observations.append("Use LAG(...) OVER (ORDER BY date) for comparisons")
        return {"score": min(score, 3.0), "observations": observations, "max_score": 5.0}

    def _validate_practice_query(self, code: str, task_id: str) -> Dict:
        score = 0.0
        observations = []
        if "SELECT" in code.upper() and "FROM" in code.upper():
            observations.append("✅ Valid SQL structure")
            score += 2.0
        if "workspace.edufin_small" in code:
            observations.append("✅ Correct dataset")
            score += 1.0
        return {"score": min(score, 3.0), "observations": observations, "max_score": 5.0}

