        if KNOWLEDGE_LOADED:
            try:
                kb_context = knowledge.get_context_for_file(file_path, code)
            except Exception as e:
                print(f"⚠️ Knowledge base lookup failed: {e}")

        # Collect specific findings
        observations = []
        action_items = []
        architectural_questions = []

        # Run checks based on file type
        if file_path.endswith(".py"):
            obs, actions = self._review_python(code, file_path, kb_context)
            observations.extend(obs)
            action_items.extend(actions)
        elif file_path.endswith(".sql"):
            obs, actions = self._review_sql(code, kb_context)
            observations.extend(obs)
            action_items.extend(actions)
        elif file_path.endswith((".md", ".txt")):
            obs, actions = self._review_docs(code, pr_title, kb_context)
            observations.extend(obs)
            action_items.extend(actions)

        # Generate architectural questions using knowledge base
        if KNOWLEDGE_LOADED and kb_context:
            try:
                arch_questions = knowledge.get_review_questions(file_path, code, observations)
                architectural_questions.extend(arch_questions)
            except Exception as e:
                print(f"⚠️ Question generation failed: {e}")

        # Determine status
        if any("CRITICAL" in o for o in observations):
            status = "NEEDS_REWORK"
            status_emoji = "🔴"
        elif observations:
            status = "NEEDS_POLISH"
            status_emoji = "🟡"
        else:
            status = "SOLID"
            status_emoji = "🟢"

        # Build Viresh-style feedback
        feedback = self._build_viresh_feedback(
            file_path=file_path,
            author=author,
            status_emoji=status_emoji,
            observations=observations,
            action_items=action_items,
            architectural_questions=architectural_questions,
            kb_context=kb_context
        )

        return {
            "status": status,
            "feedback": feedback,
            "inline_comments": [],
            "file_path": file_path
        }

    def _review_python(self, code: str, file_path: str, kb_context: Dict = None) -> tuple:
        """Python-specific review with knowledge base enhancement"""
        observations = []
        actions = []

        # Check 1: Hardcoded numbers (filter business rules + kb patterns)
        magic_nums = []
        for match in re.finditer(r'\b\d{3,}\b', code):
            num = match.group()
            if num in self.EDUFIN_BUSINESS_RULES:
                continue
            line = code[:match.start()].count('\n') + 1
            context = code[max(0, match.start()-20):match.start()+20]
            if '#' not in context and '"' not in context and "'" not in context:
                magic_nums.append((line, num))

        if len(magic_nums) > 3:
            sample_lines = ", ".join([str(l) for l, _ in magic_nums[:5]])
            sample_nums = set([n for _, n in magic_nums[:5]])
            observations.append(
                f"Hardcoded numbers detected on lines {sample_lines}{' and more' if len(magic_nums) > 5 else ''} "
                f"(values like {', '.join(sample_nums)}). Are these business rules or magic numbers?"
            )

            # Enhanced action based on knowledge base
            if kb_context and 'hardcoded_values' in str(kb_context.get('common_issues', [])):
                actions.append(
                    "Review all hardcoded numbers. Per SkillAIPath standards: extract business constants "
                    "to a config file or constants section. For one-off values, add inline comments. "
                    "Use environment variables for any deployment-specific values."
                )
            else:
                actions.append(
                    "Review all hardcoded numbers. If they're business constants, extract them to a config "
                    "file or constants section at the top. If they're one-off values, add inline comments."
                )

        # Check 2: Error handling with KB enhancement
        has_try = "try:" in code
        io_ops = []
        if "spark.read" in code: io_ops.append("spark.read")
        if "spark.sql" in code: io_ops.append("spark.sql")
        if "open(" in code: io_ops.append("file I/O")
        if "requests." in code: io_ops.append("HTTP requests")

        if io_ops and not has_try:
            observations.append(
                f"CRITICAL - No error handling around I/O operations ({', '.join(io_ops)}). "
                "What happens when the table doesn't exist or the API times out?"
            )

            # Enhanced action based on knowledge base
            if kb_context and any('error_handling' in str(std) for std in kb_context.get('coding_standards', [])):
                actions.append(
                    "SkillAIPath standard: Wrap all I/O operations in try/except blocks. "
                    "Use specific exceptions (FileNotFoundError, requests.Timeout) not bare except. "
                    "Log errors with context - not just the exception message. "
                    "Example: logger.error(f'Failed to read table {table_name}: {str(e)}')"
                )
            else:
                actions.append(
                    "Wrap I/O operations in try/except blocks. At minimum, catch the exception and "
                    "log a meaningful error message so you can debug failures."
                )

        # Check 3: Spark-specific patterns (if knowledge base detects Spark usage)
        if kb_context and any('spark' in str(std).lower() for std in kb_context.get('coding_standards', [])):
            if '.collect()' in code and 'LIMIT' not in code.upper():
                observations.append(
                    "Using .collect() without LIMIT - this can pull huge datasets into driver memory."
                )
                actions.append(
                    "SkillAIPath Spark pattern: Avoid .collect() on large datasets. "
                    "Use .show(), .take(n), or write to Delta table instead. "
                    "If you must collect, add .limit(1000) or similar first."
                )

        # Check 4: Unity Catalog usage
        if 'spark.sql' in code or 'spark.read' in code:
            if 'catalog.' not in code and 'hive_metastore' not in code:
                observations.append(
                    "Tables accessed without Unity Catalog 3-level namespace (catalog.schema.table)."
                )
                actions.append(
                    "SkillAIPath standard: Always use catalog.schema.table format. "
                    "Never rely on default catalog or 2-level names in production code."
                )

        # Check 5: Docstrings (existing logic)
        funcs = list(re.finditer(r'def (\w+)\(', code))
        funcs_no_docs = []
        for match in funcs:
            func_name = match.group(1)
            if func_name.startswith('_'):
                continue
            func_start = match.end()
            next_100 = code[func_start:func_start+100]
            if '"""' not in next_100 and "'''" not in next_100:
                funcs_no_docs.append(func_name)

        if len(funcs_no_docs) >= 3:
            observations.append(
                f"Functions {', '.join([f'`{n}`' for n in funcs_no_docs[:3]])} "
                f"{'and others ' if len(funcs_no_docs) > 3 else ''}have no docstrings. "
                "What do they do? What are the inputs/outputs?"
            )
            actions.append(
                "Add docstrings to public functions. Doesn't need to be verbose - just explain "
                "what it does, what it expects, and what it returns."
            )

        return observations, actions

    def _review_sql(self, code: str, kb_context: Dict = None) -> tuple:
        """SQL-specific review with knowledge base enhancement"""
        observations = []
        actions = []

        code_upper = code.upper()

        # Check 1: Dangerous operations
        dangerous = []
        if re.search(r'UPDATE\s+\w+', code_upper):
            if "WHERE" not in code_upper[code_upper.find("UPDATE"):code_upper.find("UPDATE")+200]:
                dangerous.append("UPDATE without WHERE")

        if re.search(r'DELETE\s+FROM', code_upper):
            if "WHERE" not in code_upper[code_upper.find("DELETE"):code_upper.find("DELETE")+200]:
                dangerous.append("DELETE without WHERE")

        if dangerous:
            observations.append(
                f"CRITICAL - {' and '.join(dangerous)} detected. You're modifying/deleting ALL rows. "
                "Is this really what you want?"
            )
            actions.append(
                "Add WHERE clauses to scope the operation. Even if you want to affect all rows, "
                "make it explicit with a comment explaining why."
            )

        # Check 2: SELECT * with KB enhancement
        if "SELECT *" in code_upper and "LIMIT" not in code_upper:
            observations.append(
                "SELECT * without LIMIT. In development, this can scan massive tables and waste time/resources."
            )

            if kb_context:
                actions.append(
                    "SkillAIPath SQL standard: Add LIMIT 100 for testing. "
                    "Once confirmed, specify exact columns (never SELECT * in production). "
                    "Use EXPLAIN to check query plan and optimize."
                )
            else:
                actions.append(
                    "Add LIMIT 100 (or whatever makes sense) for testing. Once you confirm the query works, "
                    "remove LIMIT or specify exact columns you need."
                )

        # Check 3: Unity Catalog format
        if kb_context and 'unity_catalog' in str(kb_context.get('relevant_patterns', [])):
            if '.' not in code or code.count('.') < 2:
                observations.append(
                    "Missing Unity Catalog 3-level namespace. All tables should be catalog.schema.table."
                )
                actions.append(
                    "Update to use full 3-level namespace: catalog.schema.table. "
                    "This ensures the query works across environments."
                )

        return observations, actions

    def _review_docs(self, content: str, pr_title: str, kb_context: Dict = None) -> tuple:
        """Documentation review with knowledge base enhancement"""
        observations = []
        actions = []

        # Check 1: Too short
        if len(content) < 500 and ".md" in pr_title.lower():
            observations.append(
                f"Documentation is {len(content)} characters - this is more of a stub than real docs. "
                "Current version is maybe 25% of what we need."
            )

            if kb_context:
                questions = kb_context.get('questions_to_ask', [])
                if questions:
                    actions.append(
                        f"Expand docs to cover: {', '.join(questions)}. "
                        "Include code examples and architecture context per SkillAIPath standards."
                    )
                else:
                    actions.append(
                        "Expand with actual schema definitions, table names, setup steps, examples. "
                        "See other SkillAIPath READMEs for reference structure."
                    )
            else:
                actions.append(
                    "Expand with actual schema definitions, table names, setup steps, examples."
                )

        # Check 2: Missing code examples
        if 'python' in pr_title.lower() or 'sql' in pr_title.lower():
            if '```' not in content:
                observations.append(
                    "No code examples found. Documentation for code should show usage."
                )
                actions.append(
                    "Add code examples showing how to use this. "
                    "SkillAIPath standard: Include both basic usage and a real-world example."
                )

        return observations, actions

    def _build_viresh_feedback(
        self, 
        file_path: str, 
        author: str, 
        status_emoji: str, 
        observations: List[str],
        action_items: List[str],
        architectural_questions: List[str] = None,
        kb_context: Dict = None
    ) -> str:
        """Build conversational feedback in Viresh style + project context"""

        architectural_questions = architectural_questions or []

        # Opening hooks (randomized)
        openings = [
            f"Alright {author}, let's talk about `{file_path}`.",
            f"Checking out `{file_path}` - here's what jumped out at me.",
            f"Took a look at `{file_path}`. A few things:",
            f"Quick review of `{file_path}` - couple notes:"
        ]
        opening = random.choice(openings)

        feedback = f"{status_emoji} **{opening}**\n\n"

        # Add knowledge base context note if loaded
        if KNOWLEDGE_LOADED and kb_context:
            feedback += "*Reviewed against SkillAIPath architecture & coding standards*\n\n"

        # Observations
        if observations:
            feedback += "**What I see:**\n"
            for i, obs in enumerate(observations, 1):
                feedback += f"{i}. {obs}\n"
            feedback += "\n"

        # Architectural questions (from knowledge base)
        if architectural_questions:
            feedback += "**Architectural questions:**\n"
            for i, question in enumerate(architectural_questions, 1):
                feedback += f"{i}. {question}\n"
            feedback += "\n"

        # Action items
        if action_items:
            feedback += "**What to do:**\n"
            for i, action in enumerate(action_items, 1):
                feedback += f"{i}. {action}\n"
            feedback += "\n"

        # Closing hooks (randomized)
        if status_emoji == "🟢":
            closings = [
                "Looks solid. Ship it.",
                "Good work. No blockers here.",
                "Clean. Ready to merge.",
                "Nothing critical. Approve."
            ]
        elif status_emoji == "🔴":
            closings = [
                "Fix these before merge - they'll break in production.",
                "These are blockers. Address them and ping me.",
                "Can't approve with these issues. Fix and resubmit.",
                "Critical items above. Get them resolved."
            ]
        else:
            closings = [
                "Fix these when you can - not blockers but worth addressing.",
                "Not critical, but clean these up for maintainability.",
                "Polish these and we're good.",
                "Address these and resubmit for approval."
            ]

        feedback += random.choice(closings)

        return feedback

