def send_pagerduty_alert(title, message):
    """
    Send critical alert to PagerDuty for on-call engineer
    """
    api_key = "YOUR_PAGERDUTY_API_KEY"
    service_key = "YOUR_SERVICE_KEY"

    payload = {
