            "summary": title,
            "severity": "critical",
            "source": "bharatmart-monitoring",
            "custom_details": {
                "message": message
            }
        }
    }

    response = requests.post(
        "https://events.pagerduty.com/v2/enqueue",
        headers={"Content-Type": "application/json"},
        json=payload
    )

    return response.status_code == 202
