def ndcg_at_k(actual, predicted, k=10):
    """Calculate NDCG@K"""
    if len(predicted) > k:
        predicted = predicted[:k]

    dcg = 0.0
    for i, item in enumerate(predicted):
        if item in actual:
            dcg += 1.0 / np.log2(i + 2)

    ideal_dcg = sum([1.0 / np.log2(i + 2) for i in range(min(len(actual), k))])

    if ideal_dcg == 0:
        return 0.0

    return dcg / ideal_dcg

