class Linters:
    """Static analysis linters."""

    @staticmethod
    def run_pylint(file_path: str) -> List[Dict]:
        """
        Run pylint on Python file.

        Returns:
            List of issues: [{line, column, message, severity}]
        """
        try:
            result = subprocess.run(
                ["pylint", file_path, "--output-format=json"],
                capture_output=True,
                text=True,
                timeout=30
            )

            if result.stdout:
                issues = json.loads(result.stdout)
                return [{
                    "line": issue["line"],
                    "column": issue.get("column", 0),
                    "message": issue["message"],
                    "severity": issue["type"],
                    "tool": "pylint"
                } for issue in issues]
            return []
        except Exception as e:
            print(f"⚠️ Pylint failed: {str(e)}")
            return []

    @staticmethod
    def run_flake8(file_path: str) -> List[Dict]:
        """
        Run flake8 on Python file.

        Returns:
            List of issues
        """
        try:
            result = subprocess.run(
                ["flake8", file_path, "--format=json"],
                capture_output=True,
                text=True,
                timeout=30
            )

            if result.stdout:
                data = json.loads(result.stdout)
                issues = []
                for file, file_issues in data.items():
                    for issue in file_issues:
                        issues.append({
                            "line": issue["line_number"],
                            "column": issue["column_number"],
                            "message": issue["text"],
                            "severity": "warning",
                            "tool": "flake8"
                        })
                return issues
            return []
        except Exception as e:
            print(f"⚠️ Flake8 failed: {str(e)}")
            return []

    @staticmethod
    def run_sqlfluff(file_path: str, dialect: str = "databricks") -> List[Dict]:
        """
        Run sqlfluff on SQL file.

        Returns:
            List of issues
        """
        try:
            result = subprocess.run(
                ["sqlfluff", "lint", file_path, f"--dialect={dialect}", "--format=json"],
                capture_output=True,
                text=True,
                timeout=30
            )

            if result.stdout:
                data = json.loads(result.stdout)
                issues = []
                for file_data in data:
                    for violation in file_data.get("violations", []):
                        issues.append({
                            "line": violation["line_no"],
                            "column": violation["line_pos"],
                            "message": violation["description"],
                            "severity": violation["severity"],
                            "tool": "sqlfluff"
                        })
                return issues
            return []
        except Exception as e:
            print(f"⚠️ SQLFluff failed: {str(e)}")
            return []

