    def search(self, query: str, top_k: int = 5) -> pd.DataFrame:
        """BM25-style keyword search using SQL LIKE"""
        try:
            # Simple keyword search (production would use proper BM25)
            keywords = query.lower().split()
            where_clause = " OR ".join([f"LOWER(text_content) LIKE '%{kw}%'" for kw in keywords])

            sql_query = f"""
                SELECT *
                FROM {self.kb_table}
                WHERE {where_clause}
                LIMIT {top_k}
            """

            # Execute using Databricks SQL
            connection = sql.connect(
