    """Run a pipeline stage with retry logic (StartHere pattern)"""
    success = False
    attempts = 0

    while not success and attempts < max_attempts:
        attempts += 1
        try:
            if attempts > 1:
                print(f"  Retry {attempts-1}/{max_attempts-1}...")

            result = stage_func()
            success = True
            return result

