    def get_context_for_file(self, file_path: str, code: str) -> Dict:
        """Get relevant context for reviewing a specific file"""
        if not self.docs_loaded:
            self.load_all_docs()

        context = {
            'relevant_patterns': [],
            'coding_standards': [],
            'common_issues': [],
            'questions_to_ask': []
        }

        # Determine file type and relevant context
        if file_path.endswith('.py'):
            context['coding_standards'].extend(self.coding_standards['python']['error_handling'])
            context['coding_standards'].extend(self.coding_standards['python']['documentation'])

            if 'spark' in code.lower():
                context['coding_standards'].extend(self.coding_standards['python']['spark'])
                context['relevant_patterns'].append(self.architecture_patterns['medallion'])

            if 'app.py' in file_path or 'fastapi' in code.lower() or 'flask' in code.lower():
                context['relevant_patterns'].append(self.architecture_patterns['databricks_apps'])

            # Check for anti-patterns
            if any(pattern in code for pattern in ['password', 'token', 'api_key', '127.0.0.1']):
                context['common_issues'].append(self.task_patterns['anti_patterns']['hardcoded_values'])

            if 'spark.read' in code or 'requests.' in code or 'open(' in code:
                if 'try:' not in code:
                    context['common_issues'].append(self.task_patterns['anti_patterns']['missing_error_handling'])

        elif file_path.endswith('.sql'):
            context['coding_standards'].extend(self.coding_standards['sql']['best_practices'])
            context['coding_standards'].extend(self.coding_standards['sql']['unity_catalog'])
            context['relevant_patterns'].append(self.architecture_patterns['unity_catalog'])

            code_upper = code.upper()
            if 'UPDATE' in code_upper or 'DELETE' in code_upper:
                if 'WHERE' not in code_upper:
                    context['common_issues'].append({
                        'issue': 'UPDATE/DELETE without WHERE',
                        'fix': 'Add WHERE clause to scope the operation',
                        'severity': 'CRITICAL'
                    })

        elif file_path.endswith('.md'):
            context['coding_standards'].extend(self.coding_standards['python']['documentation'])
            context['questions_to_ask'].extend([
                'Is there a clear purpose/overview?',
                'Are there code examples?',
                'Is the architecture explained?',
                'Are there setup instructions?'
            ])

        return context

    def get_review_questions(self, file_path: str, code: str, observations: List[str]) -> List[str]:
        """Generate Viresh-style architectural questions based on code"""
        questions = []

        # Architecture questions
        if 'spark.read' in code:
            if 'bronze' not in code.lower() and 'silver' not in code.lower():
                questions.append(
                    "Which layer is this in the medallion architecture? "
                    "Bronze (raw), Silver (cleaned), or Gold (aggregated)?"
                )

        if 'def ' in code and file_path.endswith('.py'):
            if 'logging' not in code:
                questions.append(
                    "How will you debug this in production? "
                    "Consider adding logging at key decision points."
                )

        if any('hardcoded' in obs.lower() for obs in observations):
            questions.append(
                "What happens when you deploy to staging or production? "
                "Will these hardcoded values still work?"
            )

        if 'exception' in code.lower():
            if 'log' not in code.lower():
                questions.append(
                    "When this exception is caught, how will you know what went wrong? "
                    "Add logging with context."
                )

        if 'UPDATE' in code.upper() or 'DELETE' in code.upper():
            questions.append(
                "Can you walk me through what rows this will affect? "
                "Show me the WHERE clause logic."
