    """Fetch changed files"""
    if not GITHUB_TOKEN: return []

    try:
        headers = {
            "Authorization": f"Bearer {GITHUB_TOKEN}",
            "Accept": "application/vnd.github.v3+json"
        }

        files_url = f"https://api.github.com/repos/{repo}/pulls/{pr_number}/files"
        r = requests.get(files_url, headers=headers, timeout=15)

        if r.status_code != 200: return []

        files = r.json()
        pr_files = []

        for file in files[:10]:
            filename = file.get("filename", "")
            if any(filename.endswith(ext) for ext in [".png", ".jpg", ".gif", ".pdf", ".zip"]):
                continue

            contents_url = file.get("contents_url")
            if contents_url:
                try:
                    content_r = requests.get(contents_url, headers=headers, timeout=10)
                    if content_r.status_code == 200:
                        content_json = content_r.json()
                        if 'content' in content_json:
                            decoded = base64.b64decode(content_json['content']).decode('utf-8')
                            pr_files.append({
                                "path": filename,
                                "content": decoded
                            })
                except: continue

        return pr_files
    except:
