def post_review_to_github(repo: str, pr_number: int, review_body: str, status: str, commit_sha: str) -> bool:
    """Post review to GitHub - NO INLINE COMMENTS"""
    if not GITHUB_TOKEN:
        print("❌ No GITHUB_TOKEN")
        return False

    if status == "SOLID":
        decision = "APPROVE"
    elif status == "NEEDS_REWORK":
        decision = "REQUEST_CHANGES"
    else:
        decision = "COMMENT"

    headers = {
        "Authorization": f"Bearer {GITHUB_TOKEN}",
        "Accept": "application/vnd.github.v3+json"
    }

    url = f"https://api.github.com/repos/{repo}/pulls/{pr_number}/reviews"

    payload = {
        "body": review_body,
        "event": decision,
        "commit_id": commit_sha
    }

    try:
        print(f"📤 Posting to: {url}")
        print(f"   Decision: {decision}")
        print(f"   Commit: {commit_sha[:8]}...")

        r = requests.post(url, headers=headers, json=payload, timeout=15)

        if r.status_code in [200, 201]:
            print(f"✅ Posted review to PR #{pr_number}")
            return True
