    if not pr_url or not review_body:
        return "❌ Need PR URL and review text"

    try:
        parts = pr_url.rstrip("/").split("/")
        repo = f"{parts[-4]}/{parts[-3]}"
        num = int(parts[-1])

        review_id = f"{repo}_{num}"

        commit_sha = ""
        with pending_lock:
            for key, review in pending_reviews.items():
                if key.startswith(review_id):
                    commit_sha = review.get("commit_sha", "")
                    break

        if not commit_sha:
            return "❌ Commit SHA not found - re-analyze first"

        if "🔴" in review_body:
            status = "NEEDS_REWORK"
        elif "🟢" in review_body:
            status = "SOLID"
        else:
            status = "NEEDS_POLISH"

        success = post_review_to_github(repo, num, review_body, status, commit_sha)

        if success:
            review_data = {
                "review_id": f"{repo}_{num}_{int(time.time())}",
